// GetSupervisorAgentStatus handles GET /api/dve/{nodeId}/supervisor-agent/status
// Returns the current health status of the KNIRVAGENT supervisor for this DVE.
// If the node exists but no agent is running yet, it attempts to start one (lazy provisioning).
func (h *DVEHandlers) GetSupervisorAgentStatus(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if h.knirvagentManager == nil {
		json.NewEncoder(w).Encode(map[string]interface{}{
			"status": "unavailable",
			"error":  "KNIRVAGENT supervisor not configured",
		})
		return
	}

	nodeID := mux.Vars(r)["nodeId"]

	// Lazy-provision: if no agent is running for THIS specific DVE, start one.
	// Check per-DVE socket — not just "any agent running" — so that accessing a
	// second DVE while a first DVE's agent is active still triggers provisioning.
	if _, sockErr := h.knirvagentManager.GetSocketPathForDVE(nodeID); sockErr != nil && h.dveManager != nil && nodeID != "" {
		if node, err := h.dveManager.GetNode(nodeID); err == nil && node != nil {
			log.Printf("[DVE] Lazy-provisioning KNIRVAGENT for node %s (%s)", nodeID, node.Name)
			startCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
			defer cancel()
			if err := h.knirvagentManager.StartAgent(startCtx, nodeID, 30*time.Second); err != nil {
				log.Printf("[DVE] Lazy-provisioning failed for node %s: %v", nodeID, err)
			}
		}
	}

	// Check per-DVE status
	status := "offline"
	if _, err := h.knirvagentManager.GetSocketPathForDVE(nodeID); err == nil {
		status = "online"
	} else if h.knirvagentManager.IsRunning() {
		status = "initializing"
	}
	running := status != "offline"

	healthCtx, healthCancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer healthCancel()
	healthErr := h.knirvagentManager.HealthCheck(healthCtx)
	healthStatus := "healthy"
	if healthErr != nil {
		healthStatus = "unhealthy"
	}
	// Override health if we just provisioned (socket might not be ready yet)
	if status == "initializing" {
		healthStatus = "booting"
	}

	json.NewEncoder(w).Encode(map[string]interface{}{
		"status":        status,
		"health":        healthStatus,
		"running":       running,
		"base_url":      h.knirvagentManager.GetBaseURL(),
		"agent_type":    "knirvagent",
		"role":          "supervisor",
		"node_id":       nodeID,
		"timestamp":     getCurrentTimestamp(),
	})
}

// GetSupervisorAgentSession handles GET /api/dve/{nodeId}/supervisor-agent/session
// Returns a WebSocket URL for real-time communication with the KNIRVAGENT supervisor.
// If the node exists but no agent is running, attempts lazy provisioning first.
func (h *DVEHandlers) GetSupervisorAgentSession(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	nodeID := mux.Vars(r)["nodeId"]

	if h.knirvagentManager == nil {
		w.WriteHeader(http.StatusServiceUnavailable)
		json.NewEncoder(w).Encode(map[string]interface{}{
			"error": "KNIRVAGENT supervisor not configured",
		})
		return
	}

	// Lazy-provision if no agent is running for THIS specific DVE (regardless of
	// whether agents for other DVEs are already running).
	if _, sockErr := h.knirvagentManager.GetSocketPathForDVE(nodeID); sockErr != nil && h.dveManager != nil && nodeID != "" {
		if node, err := h.dveManager.GetNode(nodeID); err == nil && node != nil {
			log.Printf("[DVE] Lazy-provisioning KNIRVAGENT for session on node %s (%s)", nodeID, node.Name)
			startCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
			defer cancel()
			if err := h.knirvagentManager.StartAgent(startCtx, nodeID, 30*time.Second); err != nil {
				log.Printf("[DVE] Lazy-provisioning failed for session on node %s: %v", nodeID, err)
			}
		}
	}

	// Verify the agent socket exists for this specific DVE (covers both
	// "never started" and "failed to provision" cases).
	if _, err := h.knirvagentManager.GetSocketPathForDVE(nodeID); err != nil {
		w.WriteHeader(http.StatusServiceUnavailable)
		json.NewEncoder(w).Encode(map[string]interface{}{
			"error": "KNIRVAGENT not available for this DVE: " + err.Error(),
		})
		return
	}

	// The session URL points to the backend WebSocket proxy which relays
	// I/O between the frontend terminal and the KNIRVAGENT subprocess.
	wsURL := fmt.Sprintf("/ws/dve/%s/agent", nodeID)

	json.NewEncoder(w).Encode(map[string]interface{}{
		"ws_url":    wsURL,
		"base_url":  h.knirvagentManager.GetBaseURL(),
		"running":   true,
		"timestamp": getCurrentTimestamp(),
	})
}

// RegisterRoutes registers the DVE routes with the router
func (h *DVEHandlers) RegisterRoutes(r *mux.Router, authMiddleware *middleware.AuthMiddleware) {
	// Create a subrouter for DVE endpoints
	dveRouter := r.PathPrefix("/api/dve-nodes").Subrouter()

	// Routes with optional auth (for role-based filtering)

// StartAgent spawns a new KNIRVAGENT subprocess for the given DVE ID.
// It blocks until the agent's socket is ready (up to StartTimeout).
func (am *AgentManager) StartAgent(ctx context.Context, dveID string, startTimeout time.Duration) (*AgentProcess, error) {
	am.mu.Lock()

	// Check if already running
	if existing, ok := am.agents[dveID]; ok && existing.isHealthy() {
		am.mu.Unlock()
		am.logger.Info("Agent already running for DVE", zap.String("dveID", dveID))
		return existing, nil
	}

	// Check max concurrent limit
	if len(am.agents) >= am.maxConcurrent {
		am.mu.Unlock()
		return nil, fmt.Errorf("max concurrent agents reached (%d/%d)",
			len(am.agents), am.maxConcurrent)
	}

	resolvedPath := am.binaryPath
	if resolvedPath == "" {
		var err error
		resolvedPath, err = resolveBinaryPath("./knirvagent")
		if err != nil {
			am.mu.Unlock()
			return nil, fmt.Errorf("KNIRVAGENT binary not found: %w", err)
		}
	}

	if am.socketDir != "" {
		if err := os.MkdirAll(am.socketDir, 0755); err != nil {
			am.mu.Unlock()
			return nil, fmt.Errorf("failed to create socket dir %s: %w", am.socketDir, err)
		}
	}

	socketPath := filepath.Join(am.socketDir, fmt.Sprintf("agent-%s.sock", dveID))

	// Kill any stale instance for this DVE
	killStaleAgent(resolvedPath)
	os.Remove(socketPath)

	am.logger.Info("Starting KNIRVAGENT for DVE",
		zap.String("dveID", dveID),
		zap.String("socket", socketPath),
		zap.String("binary", resolvedPath))

	// Build command — the agent runs the `server` subcommand which listens
	// on a Unix socket (agent-{dveID}.sock) and exposes POST /api/execute.
	args := []string{
		"server",
		"--dve-id", dveID,
		"--socket-path", socketPath,
	}

	cmd := exec.Command(resolvedPath, args...)
	cmd.Env = os.Environ()
	cmd.Env = append(cmd.Env, am.extraEnv...)

	// If we have a per-DVE workspace resolver, export it for this subprocess so
	// both the supervisor and inner PTY sessions operate on the DVE workspace.
	am.mu.RLock()
	resolver := am.workspaceResolver
	am.mu.RUnlock()
	if resolver != nil {
		if wsPath, err := resolver(dveID); err == nil && wsPath != "" {
			cmd.Env = append(cmd.Env,
				fmt.Sprintf("KNIRV_AGENTS_DEFAULTS_WORKSPACE=%s", wsPath),
				"KNIRV_AGENTS_DEFAULTS_RESTRICT_TO_WORKSPACE=true",
			)
		}
	}
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.SysProcAttr = &syscall.SysProcAttr{
		Setpgid: true,
	}

	if err := cmd.Start(); err != nil {
		am.mu.Unlock()
		return nil, fmt.Errorf("failed to start KNIRVAGENT for DVE %s: %w", dveID, err)
	}

	pid := cmd.Process.Pid

	ap := &AgentProcess{
		DVEID:      dveID,
		Cmd:        cmd,
		SocketPath: socketPath,
		PID:        pid,
		StartedAt:  time.Now(),
		Healthy:    false,
	}

	am.agents[dveID] = ap
	am.mu.Unlock()

	// Wait for the socket to appear (outside the lock)
	if startTimeout <= 0 {
		startTimeout = 30 * time.Second
	}
	if !waitForSocket(socketPath, startTimeout) {
		// Socket didn't appear — kill the process group
		syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
		am.mu.Lock()
		delete(am.agents, dveID)
		am.mu.Unlock()
		return nil, fmt.Errorf("timeout waiting for agent socket %s for DVE %s", socketPath, dveID)
	}

	ap.setHealthy(true)

	am.logger.Info("KNIRVAGENT started for DVE",
		zap.String("dveID", dveID),
		zap.Int("pid", pid),
		zap.String("socket", socketPath))

	return ap, nil
}

// StopAgent stops the agent subprocess for the given DVE ID.
func (am *AgentManager) StopAgent(dveID string, stopTimeout time.Duration) error {
	am.mu.Lock()
	ap, ok := am.agents[dveID]
	if !ok {
		am.mu.Unlock()
		return nil // idempotent — already stopped
	}
	delete(am.agents, dveID)
	am.mu.Unlock()

	if ap.Cmd == nil || ap.Cmd.Process == nil {
		os.Remove(ap.SocketPath)
		return nil
	}

	am.logger.Info("Stopping KNIRVAGENT for DVE",
		zap.String("dveID", dveID),
		zap.Int("pid", ap.PID))

	// Send SIGTERM
	if err := ap.Cmd.Process.Signal(syscall.SIGTERM); err != nil {
		am.logger.Warn("Failed to send SIGTERM to agent, forcing kill",
			zap.String("dveID", dveID),
			zap.Error(err))
		syscall.Kill(-ap.Cmd.Process.Pid, syscall.SIGKILL)
	}

	done := make(chan error, 1)
	go func() {
		done <- ap.Cmd.Wait()
	}()

	if stopTimeout <= 0 {
		stopTimeout = 10 * time.Second
	}

	select {
	case <-done:
		ap.setHealthy(false)

